<template><div class="page-view"><div class="welcome-row"><div><h1>Relatórios</h1><p class="subcopy">Indicadores atualizados automaticamente.</p></div><button class="secondary-btn" @click="exportCsv"><Download/>Exportar CSV</button></div><div class="report-grid"><section class="panel report-card"><h2>Distribuição por status</h2><div v-for="row in rows" :key="row.label" class="report-line"><span>{{row.label}}</span><div><i :style="{width:row.percent+'%'}"/></div><strong>{{row.value}}</strong></div></section><section class="panel report-card"><h2>Resumo do fluxo</h2><div class="big-stat"><strong>{{completion}}%</strong><span>taxa de conclusão</span></div></section><section class="panel report-card wide"><h2>Desempenho por projeto</h2><div v-for="p in projects" :key="p.id" class="project-report"><span>{{p.name}}</span><div class="bar"><i :style="{width:progress(p.id)+'%',background:p.color}"/></div><strong>{{done(p.id)}}/{{total(p.id)}}</strong></div></section></div></div></template>
<script setup lang="ts">import{computed}from"vue";import{Download}from"lucide-vue-next";import type{Project,Task}from"../stores/taskflow";const props=defineProps<{tasks:Task[];projects:Project[]}>(),finished=computed(()=>props.tasks.filter(t=>t.status==="Concluída").length),completion=computed(()=>props.tasks.length?Math.round(finished.value/props.tasks.length*100):0),rows=computed(()=>["Concluída","Em andamento","Pendente"].map(s=>{const value=props.tasks.filter(t=>t.status===s).length;return{label:s,value,percent:props.tasks.length?value/props.tasks.length*100:0}}));const total=(id:number)=>props.tasks.filter(v=>v.projectId===id).length,done=(id:number)=>props.tasks.filter(v=>v.projectId===id&&v.status==="Concluída").length;function progress(id:number){return total(id)?Math.round(done(id)/total(id)*100):0}function exportCsv(){const rows=[["Tarefa","Projeto","Status","Prioridade","Prazo"],...props.tasks.map(t=>[t.title,props.projects.find(p=>p.id===t.projectId)?.name||"",t.status,t.priority,t.due])],blob=new Blob(["\ufeff"+rows.map(r=>r.map(v=>`"${v}"`).join(",")).join("\n")],{type:"text/csv"}),a=document.createElement("a");a.href=URL.createObjectURL(blob);a.download="taskflow-relatorio.csv";a.click();URL.revokeObjectURL(a.href)}</script>
